39	// handleClient manages a single WebSocket connection for its lifetime.
40	// It pushes notification events and proxies commands to the cmux socket.
41	func handleClient(
42		w http.ResponseWriter,
43		r *http.Request,
44		token string,
45		poll *poller.Poller,
46		cmuxClient *socket.Client,
47		cmuxConnected func() bool,
48	) {
49		if !validateBearer(r, token) {
50			http.Error(w, "Unauthorized", http.StatusUnauthorized)
51			return
52		}
53	
54		conn, err := websocket.Accept(w, r, &websocket.AcceptOptions{
55			InsecureSkipVerify: true, // LAN only; origins vary
56		})
57		if err != nil {
58			log.Printf("ws: accept error: %v", err)
59			return
60		}
61		defer conn.Close(websocket.StatusNormalClosure, "")
62	
63		ctx := r.Context()
64	
65		// Send initial connected event
66		_ = wsjson.Write(ctx, conn, pushMessage{
67			Type: "connected",
68			Data: map[string]any{
69				"bridge_version":   bridgeVersion,
70				"cmux_connected":   cmuxConnected(),
71				"protocol_version": 1,
72			},
73		})
74	
75		// Subscribe to poller events. The channel is never closed by Unsubscribe —
76		// the handler exits via ctx cancellation or incoming closing.
77		events := poll.Subscribe()
78		defer poll.Unsubscribe(events)
79	
80		// Channel for incoming commands from the client
81		incoming := make(chan commandRequest, 8)
82	
83		// Read loop: decode incoming commands and forward to incoming channel
84		go func() {
85			defer close(incoming)
86			for {
87				var cmd commandRequest
88				if err := wsjson.Read(ctx, conn, &cmd); err != nil {
89					return
90				}
91				select {
92				case incoming <- cmd:
93				case <-ctx.Done():
94					return
95				}
96			}
97		}()
98	
99		for {
100			select {
101			case <-ctx.Done():
102				return
103	
104			case ev := <-events:
105				if err := wsjson.Write(ctx, conn, pushMessage{
106					Type: ev.Type,
107					Data: ev.Data,
108				}); err != nil {
109					return
110				}
111	
112			case cmd, ok := <-incoming:
113				if !ok {
114					return
115				}
116				resp := proxyCommand(cmd, cmuxClient, poll)
117				if err := wsjson.Write(ctx, conn, resp); err != nil {
118					return
119				}
120			}
121		}
122	}
123	
124	func proxyCommand(cmd commandRequest, client *socket.Client, poll *poller.Poller) commandResponse {
125		result, err := client.Send(cmd.Method, cmd.Params)
126		if err != nil {
127			return commandResponse{
128				ID: cmd.ID,
129				OK: false,
130				Error: &rpcError{
131					Code:    "proxy_error",
132					Message: err.Error(),
133				},
134			}
135		}
136	
137		// After a successful notification.clear, reset the poller's seen-ID set
138		// so re-appearing notifications get pushed again.
139		if cmd.Method == "notification.clear" {
140			poll.ResetSeenIDs()
141		}
142	
143		return commandResponse{
144			ID:     cmd.ID,
145			OK:     true,
146			Result: result,
147		}
148	}
