3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"sync"
9		"time"
10	)
11	
12	// cacheEntry holds an already-rendered transcript with its file identity.
13	type cacheEntry struct {
14		modTime time.Time
15		size    int64
16		text    string
17	}
18	
19	// Resolver locates and renders Claude session transcripts.
20	type Resolver struct {
21		home  string
22		cache sync.Map // keyed by absolute path → *cacheEntry
23	}
24	
25	// NewResolver creates a Resolver that resolves $HOME via os.UserHomeDir.
26	func NewResolver() *Resolver {
27		home, _ := os.UserHomeDir()
28		return &Resolver{home: home}
29	}
30	
31	// Render returns the rendered transcript for a surface's resume_binding.
32	//
33	// supported reports whether the binding describes a Claude surface at all.
34	// If supported is true but text is empty (""), no transcript file was found yet.
35	// sessionID is the base filename (without .jsonl) of the active transcript.
36	func (r *Resolver) Render(resumeBinding map[string]any, maxMessages int) (text string, supported bool, sessionID string, err error) {
37		if resumeBinding == nil {
38			return "", false, "", nil
39		}
40		kind, _ := resumeBinding["kind"].(string)
41		if kind != "claude" {
42			return "", false, "", nil
43		}
44	
45		projectDir, err := r.resolveProjectDir(resumeBinding)
46		if err != nil {
47			return "", true, "", err
48		}
49		if projectDir == "" {
50			// Claude surface but no transcript directory yet.
51			return "", true, "", nil
52		}
53	
54		transcriptPath, err := latestJSONL(projectDir)
55		if err != nil {
56			return "", true, "", err
57		}
58		if transcriptPath == "" {
59			return "", true, "", nil
60		}
61	
62		sessionID = strings.TrimSuffix(filepath.Base(transcriptPath), ".jsonl")
63	
64		info, err := os.Stat(transcriptPath)
65		if err != nil {
66			return "", true, sessionID, err
67		}
68	
69		// Check cache.
70		if v, ok := r.cache.Load(transcriptPath); ok {
71			entry := v.(*cacheEntry)
72			if entry.modTime.Equal(info.ModTime()) && entry.size == info.Size() {
73				return entry.text, true, sessionID, nil
74			}
75		}
76	
77		data, err := os.ReadFile(transcriptPath)
78		if err != nil {
79			return "", true, sessionID, err
80		}
81	
82		rendered := renderJSONL(data, maxMessages)
83		r.cache.Store(transcriptPath, &cacheEntry{
84			modTime: info.ModTime(),
85			size:    info.Size(),
86			text:    rendered,
87		})
88		return rendered, true, sessionID, nil
89	}
90	
91	// resolveProjectDir returns the ~/.claude/projects/<enc> directory that
92	// contains the active session for the given resume_binding, or "" if not found.
93	func (r *Resolver) resolveProjectDir(rb map[string]any) (string, error) {
94		projectsDir := filepath.Join(r.home, ".claude", "projects")
95	
96		// Strategy 1: use checkpoint_id to locate the exact project directory.
97		if checkpointID, _ := rb["checkpoint_id"].(string); checkpointID != "" {
98			pattern := filepath.Join(projectsDir, "*", checkpointID+".jsonl")
99			matches, err := filepath.Glob(pattern)
100			if err != nil {
101				return "", err
102			}
103			if len(matches) > 0 {
104				return filepath.Dir(matches[0]), nil
105			}
106		}
107	
108		// Strategy 2: encode the cwd.
109		if cwd, _ := rb["cwd"].(string); cwd != "" {
110			enc := encodeCWD(cwd)
111			dir := filepath.Join(projectsDir, enc)
112			if _, err := os.Stat(dir); err == nil {
113				return dir, nil
114			}
115		}
116	
117		return "", nil
118	}
119	
120	// encodeCWD converts an absolute cwd path to the Claude project directory name.
121	// e.g. "/Users/marlin/wrinkles" → "-Users-marlin-wrinkles"
122	func encodeCWD(cwd string) string {
123		stripped := strings.TrimPrefix(cwd, "/")
124		replacer := strings.NewReplacer("/", "-", ".", "-", "_", "-")
125		return "-" + replacer.Replace(stripped)
126	}
127	
128	// latestJSONL returns the most-recently-modified *.jsonl file in dir, or "".
129	func latestJSONL(dir string) (string, error) {
130		entries, err := os.ReadDir(dir)
131		if err != nil {
132			return "", err
133		}
134	
135		var bestPath string
136		var bestMod time.Time
137	
138		for _, e := range entries {
139			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
140				continue
141			}
142			full := filepath.Join(dir, e.Name())
143			info, err := e.Info()
144			if err != nil {
145				continue
146			}
147			if bestPath == "" || info.ModTime().After(bestMod) {
148				bestPath = full
149				bestMod = info.ModTime()
150			}
151		}
152		return bestPath, nil
153	}
154	
155	// ---- Pure rendering helpers (exported for tests) ----------------------------
156	
157	// jsonlLine is the top-level structure of each JSONL event line.
158	type jsonlLine struct {
159		Type    string `json:"type"`
160		Message struct {
161			Role    string          `json:"role"`
162			Content json.RawMessage `json:"content"`
163		} `json:"message"`
164	}
165	
166	// renderJSONL parses raw JSONL data and returns the rendered transcript.
167	// Only the last maxMessages user/assistant messages are included.
168	func renderJSONL(data []byte, maxMessages int) string {
169		type msg struct {
170			role string
171			text string
172		}
173	
174		var messages []msg
175		for _, rawLine := range strings.Split(string(data), "\n") {
176			rawLine = strings.TrimSpace(rawLine)
177			if rawLine == "" {
178				continue
179			}
180			var line jsonlLine
181			if err := json.Unmarshal([]byte(rawLine), &line); err != nil {
182				continue
183			}
184			if line.Type != "user" && line.Type != "assistant" {
185				continue
186			}
187			text := extractContent(line.Message.Content)
188			if strings.TrimSpace(text) == "" {
189				continue
190			}
191			messages = append(messages, msg{role: line.Message.Role, text: text})
192		}
193	
194		// Keep only the last maxMessages.
195		if maxMessages > 0 && len(messages) > maxMessages {
196			messages = messages[len(messages)-maxMessages:]
197		}
198	
199		var sb strings.Builder
200		for i, m := range messages {
201			var header string
202			if m.role == "user" {
203				header = "› You"
204			} else {
205				header = "⏺ Claude"
206			}
207			if i > 0 {
208				sb.WriteByte('\n')
209			}
210			sb.WriteString(header)
211			sb.WriteByte('\n')
212			sb.WriteString(m.text)
213			sb.WriteByte('\n')
214		}
215		return sb.String()
216	}
217	
218	// extractContent converts a raw JSON content field (string or block array)
219	// into plain text.
220	func extractContent(raw json.RawMessage) string {
221		if len(raw) == 0 {
222			return ""
223		}
224	
225		// Try string first.
226		var s string
227		if err := json.Unmarshal(raw, &s); err == nil {
228			return s
229		}
230	
231		// Try array of blocks.
232		var blocks []map[string]any
233		if err := json.Unmarshal(raw, &blocks); err != nil {
234			return ""
235		}
236	
237		var parts []string
238		for _, block := range blocks {
239			blockType, _ := block["type"].(string)
240			switch blockType {
241			case "text":
242				if t, _ := block["text"].(string); t != "" {
243					parts = append(parts, t)
244				}
245			case "tool_use":
246				if name, _ := block["name"].(string); name != "" {
247					parts = append(parts, "⚙ "+name)
248				}
249			// thinking, tool_result, and anything else: skip
250			}
251		}
252		return strings.Join(parts, "\n")
253	}
